CREATE OR REPLACE FUNCTION public.protect_held_podcast_content() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.audit_hold THEN IF NEW.audit_hold AND (NEW.script IS DISTINCT FROM OLD.script OR NEW.audio_path IS DISTINCT FROM OLD.audio_path OR NEW.status IS DISTINCT FROM OLD.status) THEN RAISE EXCEPTION 'Clinical audit hold: preserve original script, audio and status until a reviewed matching replacement is supplied'; END IF; IF NOT NEW.audit_hold AND (NEW.script IS NOT DISTINCT FROM OLD.script OR NEW.audio_path IS NOT DISTINCT FROM OLD.audio_path OR NEW.script IS NULL OR NEW.audio_path IS NULL OR NEW.status <> 'ready') THEN RAISE EXCEPTION 'Clinical audit hold release requires changed script and distinct matching audio path together'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_held_podcast_content BEFORE UPDATE ON public.podcasts FOR EACH ROW EXECUTE FUNCTION public.protect_held_podcast_content();
ALTER TABLE public.podcasts ADD CONSTRAINT podcasts_audit_hold_not_ready CHECK (NOT audit_hold OR status <> 'ready');